            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
            if opp.get('budget', 0) > budget and opp.get('hp', 0) >= hp:
                rich_aggressive = True

    alive_count = len(alive_opps)
    if alive_count == 0:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        emergency = max(78.0, highest_prev + 8.0)
        if tight_supply:
            emergency += 18.0
        return float(min(budget, emergency))

    if hp <= 4 or no_water >= 1:
        urgent = max(52.0, avg_prev + 6.0)
        if tight_supply:
            urgent = max(urgent, highest_prev + 4.0)
        return float(min(budget, urgent))

    if ample_supply:
        bid = 24.0
        if highest_prev < 25:
            bid = 19.0
        elif highest_prev < 45:
            bid = 27.0
        else:
            bid = min(36.0, highest_prev * 0.7)
        return float(min(budget, bid))

    if tight_supply:
        bid = max(38.0, avg_prev + 3.0)
        if highest_prev > 90:
            bid = 34.0
        if rich_aggressive:
            bid += 4.0
        return float(min(budget, bid))

    bid = max(30.0, avg_prev + 2.0)
    if highest_prev >= 120:
        bid = 32.0
    elif highest_prev >= 70:
        bid = 36.0
    elif highest_prev <= 30:
        bid = 28.0

    if day >= 8 and hp >= 6:
        bid = min(bid, 30.0)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    opp_prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                opp_prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate: how aggressive were surviving opponents
    if opp_prev_bids:
        max_prev = max(opp_prev_bids)
        avg_prev = sum(opp_prev_bids) / float(len(opp_prev_bids))
    else:
        max_prev = 0.0
        avg_prev = 0.0

    # Supply pressure: higher supply reduces need to outbid; lower supply increases it.
    # Normalize to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base bid target: ensure we can win when supply is tight and/or our hp is low.
    # Use yesterday aggressiveness as a proxy for current-day bids.
    # Target multiplier for bid
    hp_factor = 1.0
    if hp <= 1:
        hp_factor = 1.15
    elif hp == 2:
        hp_factor = 1.08
    elif hp >= 6:
        hp_factor = 0.92

    no_water_factor = 1.0
    if no_water_days >= 3:
        no_water_factor = 1.18
    elif no_water_days == 2:
        no_water_factor = 1.08

    # If someone was bidding near/above daily salary, we should not be too low.
    # Otherwise, bid around a fraction of that.
    aggressive_threshold = DAILY_SALARY * 0.85

    if max_prev >= aggressive_threshold:
        # Overmatch slightly vs aggressive opponents
        target = max_prev + (2.0 * (1.0 - supply_norm))
    else:
        # Moderate: aim above average but not wasteful
        target = max(avg_prev * (0.95 + 0.1 * (1.0 - supply_norm)), DAILY_SALARY * 0.45)

    # Adjust for hp and no-water pressure
    target *= hp_factor
    target *= no_water_factor

    # Convert target into a safe cap based on remaining budget
    # Also ensure we don't bid more than we can afford.
    max_affordable = max(0.0, budget)

    # Keep bids within reasonable band to avoid bankruptcy
    # Lower band: still bid something if we're in danger.
    min_reasonable = 0.0
    if hp <= 2 or no_water_days >= 2:
        min_reasonable = DAILY_SALARY * 0.65

    bid = min(max_affordable, target)
    if bid < min_reasonable:
        bid = min(max_affordable, min_reasonable)

    # Final sanity
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    # Scarcity factor
    supply = day_context['supply']
    num_competitors = len(alive_opponents) + 1
    fair_share = supply / num_competitors

    bid = avg_prev
    if fair_share < WATER_REQ:
        bid = max(bid, DAILY_SALARY * 0.8)
    elif fair_share > WATER_REQ * 1.5:
        bid = min(bid, DAILY_SALARY * 0.4)

    # HP Protection
    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 0.95)

    return min(my_status['budget'], max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Estimate opponent bids from yesterday's trace
    opp_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            opp_bids.append(prev['bid'])

    # Determine target bid
    target_bid = DAILY_SALARY * 0.6  # baseline
    if opp_bids:
        max_prev = max(opp_bids)
        # Cindy-like high bidder
        if max_prev > DAILY_SALARY * 1.2:
            if my_status['hp'] > 4:
                target_bid = min(max_prev + 0.1, DAILY_SALARY * 0.7)
            else:
                target_bid = min(max_prev + 0.5, DAILY_SALARY * 0.95)
        else:
            target_bid = max(DAILY_SALARY * 0.5, max_prev + 0.2)

    # Adjust for low HP
    if my_status['hp'] <= 2:
        target_bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 4:
        target_bid = max(target_bid, DAILY_SALARY * 0.75)

    # Ensure we don't exceed budget
    bid = min(my_status['budget'], target_bid)
    return max(0, bid)
